anki_custom_css:
/* Create a distinct, minimalist dark canvas block */
.sjr-dictionary {
    font-family: -apple-system, "Segoe UI", Roboto, Helvetica, sans-serif;
    line-height: 1.6;
    background-color: #191919 !important;
    padding: 16px;
    border-radius: 6px;
    border: 1px solid #333 !important;
    margin-top: 10px;
}

/* Strip the standard lists */
.sjr-dictionary ul {
    list-style-type: none;
    padding-left: 0;
    margin: 12px 0 0 0;
}

/* Sharp, vibrant accent line for the definitions */
.sjr-dictionary li {
    margin-bottom: 10px;
    padding-left: 12px;
    border-left: 2px solid #F05A28 !important; /* Sharp orange/red accent */
    color: #E0E0E0 !important; 
    font-size: 15px;
}

/* High-contrast, sharp-edged monochrome badge */
.sjr-dictionary b {
    color: #191919 !important;
    background-color: #F0F0F0 !important; 
    padding: 3px 8px;
    font-size: 11px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    display: inline-block;
    margin-bottom: 8px;
    border-radius: 2px; /* Sharp corners instead of rounded */
}
